let selectedPlayers=new Set(),bulkReview=null;
function bulkControls(){return `<div id="bulkToolbar" class="toolbar"><span id="bulkCount">0 seleccionados</span><button type="button" id="bulkOpen">Editar seleccionados</button><button type="button" id="bulkClear">Limpar selecção</button></div>`;}
function bindBulkControls(){
 $('bulkOpen').onclick=openBulkEditor;$('bulkClear').onclick=()=>{selectedPlayers.clear();drawPlayerResults();};
}
function applyBulkSelection(shown){
 $('bulkToolbar').hidden=playerBrowserView!=='table';$('bulkCount').textContent=selectedPlayers.size+' seleccionados (máximo 200)';$('bulkOpen').disabled=!selectedPlayers.size;
 if(playerBrowserView!=='table'||!shown.length)return;
 const head=$('searchResults').querySelector('th');head.insertAdjacentHTML('afterbegin','<input type="checkbox" id="bulkPage" aria-label="Seleccionar jogadores desta página"> ');
 const page=$('bulkPage');page.checked=shown.every(p=>selectedPlayers.has(p.id));page.indeterminate=!page.checked&&shown.some(p=>selectedPlayers.has(p.id));page.onchange=()=>{const next=new Set(selectedPlayers);shown.forEach(p=>page.checked?next.add(p.id):next.delete(p.id));if(next.size>200){message('Máximo de 200 jogadores por operação.');drawPlayerResults();return;}selectedPlayers=next;drawPlayerResults();};
 $('searchResults').querySelectorAll('tbody tr').forEach((row,i)=>{const p=shown[i];row.firstElementChild.insertAdjacentHTML('afterbegin',`<input type="checkbox" class="bulk-player-check" aria-label="Seleccionar ${esc(p.name)}" data-bulk-id="${p.id}" ${selectedPlayers.has(p.id)?'checked':''}> `);});
 $('searchResults').querySelectorAll('[data-bulk-id]').forEach(el=>el.onchange=()=>{const id=+el.dataset.bulkId;if(el.checked&&selectedPlayers.size>=200){el.checked=false;message('Máximo de 200 jogadores por operação.');return;}el.checked?selectedPlayers.add(id):selectedPlayers.delete(id);drawPlayerResults();});
}
function openBulkEditor(){
 if(!selectedPlayers.size||mode!=='database')return;bulkReview=null;const dialog=$('bulkDialog');
 dialog.innerHTML=`<div class="dialog-head"><h2>Edição em massa · ${selectedPlayers.size} jogadores</h2><button type="button" id="bulkClose" aria-label="Fechar">×</button></div><form id="bulkForm"><label>Alterar<select id="bulkOperation"><option value="verification">Estado de verificação</option><option value="status">Estado do jogador</option><option value="club">Clube</option><option value="source">Adicionar fonte</option></select></label><div id="bulkFields"></div><p class="muted">Só os jogadores seleccionados serão alterados. Revê as diferenças antes de confirmar. Empréstimos são tratados individualmente.</p><button type="submit" id="bulkPreview">Pré-visualizar alterações</button><p id="bulkError" role="alert"></p><div id="bulkReview"></div><button type="button" class="primary" id="bulkConfirm" hidden>Confirmar e guardar na Mestre</button></form>`;
 const fields=()=>{bulkReview=null;$('bulkConfirm').hidden=true;$('bulkReview').innerHTML='';const type=$('bulkOperation').value;$('bulkFields').innerHTML=type==='source'?`<label>Título da fonte<input id="bulkTitle" maxlength="200" required></label><label>URL (opcional)<input id="bulkUrl" type="url" maxlength="2000"></label><p class="muted">Fonte geral adicional com estado Por verificar. Não substitui fontes existentes.</p>`:`<label>${type==='club'?'Clube de destino':'Novo valor'}<select id="bulkValue">${type==='club'?'<option value="free">Sem clube</option>'+clubOptions(null):options(type==='status'?['Activo','Lesionado','Sem clube','Retirado']:Documentary.states,'Por verificar')}</select></label>`;};fields();$('bulkOperation').onchange=fields;
 $('bulkClose').onclick=()=>dialog.close();dialog.onclose=()=>{bulkReview=null;};
 $('bulkForm').oninput=()=>{bulkReview=null;$('bulkConfirm').hidden=true;$('bulkReview').innerHTML='';};
 $('bulkForm').onsubmit=e=>{e.preventDefault();try{const type=$('bulkOperation').value,operation=type==='source'?{type,source:{title:$('bulkTitle').value.trim(),url:$('bulkUrl').value.trim(),field:'general',consultedAt:'',notes:'',status:'Por verificar'}}:{type,value:type==='club'?$('bulkValue').value==='free'?null:+$('bulkValue').value:$('bulkValue').value};bulkReview=DatabaseOps.bulkPlan(master,[...selectedPlayers],operation);$('bulkReview').innerHTML=`<h3>Revisão — nada foi aplicado ainda</h3>${bulkReview.summary.map(r=>`<article><b>${esc(r.name)}</b>${r.changes.length?r.changes.map(c=>`<p>${esc(Documentary.auditFields[c.field])}: ${esc(c.before)} → ${esc(c.after)}</p>`).join(''):'<p>Sem alteração.</p>'}</article>`).join('')}`;$('bulkConfirm').hidden=false;$('bulkError').textContent='';}catch(err){bulkReview=null;$('bulkConfirm').hidden=true;$('bulkError').textContent=err.message;}};
 $('bulkConfirm').onclick=()=>{if(!bulkReview)return;if(JSON.stringify(master)!==bulkReview.baseline){$('bulkError').textContent='A base mudou. Volta a pré-visualizar as alterações.';bulkReview=null;$('bulkConfirm').hidden=true;return;}World.validate(bulkReview.candidate);master=bulkReview.candidate;s=World.context(master);selectedPlayers.clear();dialog.close();render();message(editorSaveMessage());};dialog.showModal();
}
function mountCsvExport(){
 $('app').insertAdjacentHTML('beforeend',`<section class="panel csv-export"><h2>Importar / Exportar CSV</h2><div class="toolbar"><label>Registos<select id="csvType">${Object.entries({players:'Jogadores',clubs:'Clubes',staff:'Staff',competitions:'Competições',contracts:'Contratos anteriores',transfers:'Transferências',international:'Internacionalizações',sources:'Fontes',documentaryStatistics:'Estatísticas reais',statistics:'Estatísticas do jogo'}).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><button id="csvDownload">Descarregar CSV</button><button id="csvImportOpen">Importar CSV</button></div><p class="muted">Exporta todos os registos da categoria. UTF-8, separador ponto e vírgula e relações por ID. Imagens ficam no JSON; o CSV não é uma cópia de segurança completa. As estatísticas exportadas são identificadas como dados da simulação. Importação disponível para todas as categorias documentais, com revisão antes de guardar. Estatísticas da simulação são apenas exportadas.</p></section>`);
 $('csvImportOpen').onclick=()=>openCsvImport($('csvType').value);
 $('csvType').onchange=()=>{$('csvImportOpen').disabled=!Object.hasOwn(CsvImport.types,$('csvType').value);};$('csvType').onchange();
 $('csvDownload').onclick=()=>{const type=$('csvType').value,text=DatabaseOps.exportCsv(master,type),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='helvetia-'+type+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
function drawChangeHistory(){
 const root=$('playerChangeHistory');if(!root)return;const rows=playerDraft.changeHistory||[];
 root.innerHTML='<p class="muted">Memória das edições, não acontecimentos da carreira. Remover uma entrada não repõe os valores anteriores.</p>'+rows.map((h,i)=>`<details class="change-entry"><summary>${esc(new Date(h.at).toLocaleDateString('pt-PT'))} · ${esc(h.changes.map(c=>Documentary.auditFields[c.field]).join(', '))}</summary>${h.changes.map(c=>`<p><b>${esc(Documentary.auditFields[c.field])}</b><br>${esc(c.before)} → ${esc(c.after)}</p>`).join('')}<button type="button" data-audit-remove="${i}">Remover entrada</button></details>`).reverse().join('')+(rows.length?'<button type="button" id="auditClear">Limpar registo de edições</button>':'<p class="muted">Sem edições registadas.</p>');
 root.querySelectorAll('[data-audit-remove]').forEach(b=>b.onclick=()=>{if(confirm('Remover esta entrada do registo de edições?')){playerDraft.changeHistory.splice(+b.dataset.auditRemove,1);drawChangeHistory();}});
 if($('auditClear'))$('auditClear').onclick=()=>{if(confirm('Limpar o registo de edições deste jogador? Os dados do jogador serão mantidos.')){playerDraft.changeHistory=[];drawChangeHistory();}};
}

let csvImportReview=null;
function openCsvImport(selectedType){
 const fixedType=typeof selectedType==='string'&&Object.hasOwn(CsvImport.types,selectedType)?selectedType:null;
 const dialog=$('csvImportDialog');csvImportReview=null;let request=0,matching=null,page=0,filter='all',busy=false;
 dialog.innerHTML=`<div class="dialog-head"><h2>Importar CSV</h2><button type="button" id="csvImportClose" aria-label="Fechar">×</button></div><label>Dados a importar<select id="csvImportType">${Object.entries(CsvImport.types).map(([key,label])=>`<option value="${key}">${esc(label)}</option>`).join('')}</select></label><button type="button" id="csvTemplate">Descarregar modelo CSV</button><div id="csvImportHelp"><p>Actualiza jogadores existentes pelo <b>id</b>. Usa os cabeçalhos do CSV exportado; podes conservar apenas as colunas a alterar. Campos vazios preservam o valor actual. Para libertar um jogador, usa SEM_CLUBE na coluna club.</p><p class="muted">UTF-8 · ponto e vírgula ou vírgula · datas AAAA-MM-DD · máximo 5 MB / 5000 linhas / 200 jogadores alterados. AVA é aceite como AV; active/ativo como Activo; verified/verificado como Confirmado. Empréstimos devem ser revistos individualmente. Não são importadas fotografias nem skills.</p></div><label>Ficheiro CSV<input type="file" id="csvImportFile" accept=".csv,text/csv"></label><p id="csvImportError" role="alert"></p><div id="csvImportReview"></div><button type="button" class="primary" id="csvImportConfirm" hidden>Confirmar e guardar na Mestre</button>`;
 if(fixedType){$('csvImportType').value=fixedType;$('csvImportType').parentElement.hidden=true;dialog.querySelector('h2').textContent='Importar CSV · '+CsvImport.types[fixedType];}
 const help=()=>{
  const type=$('csvImportType').value,records=['players','clubs','staff','competitions'].includes(type);
  const tips={players:'Novos jogadores exigem name e position; club é um ID ou SEM_CLUBE. Salário omitido: 0 CHF; qualidade inicial de simulação: 60. Empréstimos actuais são tratados na ficha. Fontes unificadas usam a categoria Fontes.',clubs:'Fundação aceita AAAA (apenas ano) ou AAAA-MM-DD (data completa). Novos clubes entram em div 3 / tier 4 por predefinição. As duas ligas profissionais mantêm 12 e 10 clubes. Cor omitida: cinzento; orçamento omitido: 0 CHF.',staff:'Novos membros exigem name, role e club (ID). Qualidade inicial de simulação: 60. Só pode existir um Treinador principal por clube.',competitions:'Novas competições são criadas no catálogo, sem activar um motor nem adicionar participantes. Configura o formato jogável no editor.',transfers:'Importa apenas o histórico: não altera o clube nem o empréstimo actual. Usa fromClub/toClub (IDs ou SEM_CLUBE) e loan_parent_club nos empréstimos históricos.',contracts:'Clubes externos: club = SEM_CLUBE, clubName e clubCountry. Estes contratos não alteram o vínculo actual.',international:'Uma linha por país e escalão. Usa nation, level, caps, goals e, opcionalmente, startDate/endDate. Contagens desconhecidas podem ficar vazias.',sources:'Usa title, field, url, consultedAt, notes e status. Estados: Confirmado, Parcial ou Por verificar. Fontes antigas são preservadas e adaptadas ao sistema unificado.',documentaryStatistics:'Indica season e club (ID), ou clubName/clubCountry para um clube externo. Contagens: appearances, minutes, goals e assists. Não altera estatísticas da simulação.'};
  $('csvImportHelp').innerHTML=`<p>${records?'Usa id para actualizar um registo ou <b>NOVO</b> em id para criar. Os novos IDs são apresentados na revisão.':'Usa player_id para identificar o jogador e index para a linha exportada. <b>NOVO</b> em index acrescenta uma entrada.'}</p><p>${tips[type]}</p>${type==='players'?'<p>Revê jogadores existentes, novos e correspondências duvidosas. IDs desconhecidos não substituem pessoas automaticamente. A criação atribui um ID interno novo; o ID externo não é reutilizado. Clubes continuam identificados pelos IDs desta Base Mestre.</p><p class="muted">Equivalências: AVA → AV; active/ativo → Activo; Reformado → Retirado; verified/verificado → Confirmado. Mantêm-se as 20 colunas existentes. Não são importadas fotografias nem skills.</p>':''}<p class="muted">Campos vazios preservam valores existentes. Zero é um valor explícito. UTF-8 · vírgula ou ponto e vírgula · datas AAAA-MM-DD · máximo 5 MB / 5000 linhas${type==='players'?' · sem o anterior limite de 200 jogadores':' / 200 registos ou jogadores alterados'}. Fotografias ficam no backup JSON.</p>`;
 };help();
 $('csvTemplate').onclick=()=>{const type=$('csvImportType').value,url=URL.createObjectURL(new Blob([CsvImport.template(type)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='helvetia-modelo-'+type+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('csvImportType').onchange=()=>{request++;matching=null;csvImportReview=null;$('csvImportFile').value='';$('csvImportConfirm').hidden=true;$('csvImportReview').innerHTML='';$('csvImportError').textContent='';help();};
 $('csvImportClose').onclick=()=>{request++;csvImportReview=null;dialog.close();};dialog.onclose=()=>{request++;csvImportReview=null;};
 const labels={existing:'Existentes',new:'Novos / ID desconhecido',doubtful:'Duvidosos / repetidos',invalid:'Inválidos'};
 function showMatching(){
  csvImportReview=null;$('csvImportConfirm').hidden=true;
  const list=matching.entries.filter(e=>filter==='all'||e.status===filter),pages=Math.max(1,Math.ceil(list.length/25));page=Math.min(page,pages-1);
  $('csvImportReview').innerHTML=`<h3>1. Confirmar correspondências · ${matching.read} linhas</h3><p>Nada foi guardado. Um ID igual não prova que seja a mesma pessoa. As escolhas duvidosas exigem a tua decisão.</p><label>Mostrar<select id="csvMatchFilter"><option value="all">Todas</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v} (${matching.entries.filter(e=>e.status===k).length})</option>`).join('')}</select></label><div class="toolbar"><button type="button" id="csvCreateNew">Criar todos os novos sem correspondência</button><button type="button" id="csvSkipPending">Ignorar todas as linhas ainda por decidir</button></div>${list.slice(page*25,page*25+25).map(e=>`<article class="csv-match-row"><b>Linha ${e.line} · ${esc(e.input.name||e.input.fullName||'Sem nome')} · ID CSV ${esc(e.input.id)}</b><p>${esc(labels[e.status])} — ${esc(e.reason)}</p>${e.suggestions.length?`<p>Sugestões: ${e.suggestions.slice(0,8).map(p=>esc(p.name)+' · ID '+p.id+' · '+esc(p.birthDate||'nascimento desconhecido')).join(' / ')}${e.suggestions.length>8?' / …':''}</p>`:''}<label>Acção<select data-match-action="${e.line}">${[['pending','Escolher…'],['update','Actualizar jogador existente'],['create','Criar pessoa nova'],['skip','Ignorar esta linha']].map(([k,v])=>`<option value="${k}" ${e.action===k?'selected':''}>${v}</option>`).join('')}</select></label>${e.action==='update'?`<label>ID do jogador na Base Mestre<input type="number" min="0" step="1" data-match-target="${e.line}" value="${e.targetId??''}"></label><p>${esc(master.players.find(p=>p.id===Number(e.targetId))?.name||'Escolhe um ID existente')}</p>`:''}</article>`).join('')}<div class="toolbar"><button type="button" id="csvPrev" ${page===0?'disabled':''}>Anterior</button><span>Página ${page+1} de ${pages}</span><button type="button" id="csvNext" ${page+1===pages?'disabled':''}>Seguinte</button></div><p>${matching.entries.filter(e=>e.action==='pending').length} linhas por decidir · ${matching.entries.filter(e=>e.action==='skip').length} ignoradas</p><button type="button" id="csvPrepare">Preparar e validar alterações</button>`;
  $('csvMatchFilter').onchange=e=>{filter=e.target.value;page=0;showMatching();};
  $('csvPrev').onclick=()=>{page--;showMatching();};$('csvNext').onclick=()=>{page++;showMatching();};
  $('csvCreateNew').onclick=()=>{for(const e of matching.entries)if(e.status==='new'&&e.action==='pending')e.action='create';showMatching();};
  $('csvSkipPending').onclick=()=>{for(const e of matching.entries)if(e.action==='pending')e.action='skip';showMatching();};
  dialog.querySelectorAll('[data-match-action]').forEach(el=>el.onchange=()=>{const e=matching.entries.find(e=>e.line===Number(el.dataset.matchAction));e.action=el.value;if(e.action==='update'&&e.targetId===null&&e.suggestions.length===1)e.targetId=e.suggestions[0].id;showMatching();});
  dialog.querySelectorAll('[data-match-target]').forEach(el=>el.onchange=()=>{matching.entries.find(e=>e.line===Number(el.dataset.matchTarget)).targetId=el.value===''?null:Number(el.value);showMatching();});
  $('csvPrepare').onclick=prepare;
 }
 function showPlan(){
  const plan=csvImportReview,pages=Math.max(1,Math.ceil(plan.summary.length/25));page=Math.min(page,pages-1);
  $('csvImportReview').innerHTML=`<h3>2. Rever alterações · ${plan.read} linhas · ${plan.summary.length} registos a criar / actualizar</h3><p>Nenhuma alteração foi aplicada. ${plan.skipped||0} linhas ignoradas. Ao confirmar será guardada uma cópia de recuperação da Base Mestre anterior.</p>${matching?'<button type="button" id="csvBackMatch">Voltar às correspondências</button>':''}${plan.summary.slice(page*25,page*25+25).map(r=>`<article><b>${r.created?'NOVO · ':''}${esc(r.name)} · ID ${r.id}</b>${r.changes.map(c=>`<p>${esc(Documentary.auditFields[c.field]||CsvImport.fields[c.field]||({number:'Número',theme:'Raridade'}[c.field])||c.field)}: ${esc(c.before)} → ${esc(c.after)}</p>`).join('')}</article>`).join('')}<div class="toolbar"><button type="button" id="csvPlanPrev" ${page===0?'disabled':''}>Anterior</button><span>Página ${page+1} de ${pages}</span><button type="button" id="csvPlanNext" ${page+1===pages?'disabled':''}>Seguinte</button></div>`;
  if($('csvBackMatch'))$('csvBackMatch').onclick=()=>{page=0;showMatching();};
  $('csvPlanPrev').onclick=()=>{page--;showPlan();};$('csvPlanNext').onclick=()=>{page++;showPlan();};
  $('csvImportConfirm').hidden=!plan.summary.length;$('csvImportError').textContent=plan.summary.length?'':'Sem alterações a guardar.';
 }
 async function prepare(){
  if(busy)return;const token=request;busy=true;$('csvPrepare').disabled=true;$('csvImportError').textContent='A validar pequenos lotes…';
  // Disable decisions while the review is being read; cancellation remains available.
  dialog.querySelectorAll('#csvImportReview input,#csvImportReview select,#csvImportReview button').forEach(el=>el.disabled=true);
  try{const result=await CsvImport.resolvePlayers(master,matching,{cancelled:()=>token!==request||!dialog.open,onProgress:(n,total)=>{if(token===request)$('csvImportError').textContent=`A validar ${n} de ${total} linhas…`;}});if(token!==request||!dialog.open)return;csvImportReview=result;page=0;showPlan();}
  catch(err){if(token===request&&dialog.open){showMatching();$('csvImportError').textContent=err.message;}}
  finally{busy=false;}
 }
 $('csvImportFile').onchange=async e=>{const token=++request,file=e.target.files[0];matching=null;csvImportReview=null;page=0;filter='all';$('csvImportConfirm').hidden=true;$('csvImportReview').innerHTML='';$('csvImportError').textContent='';if(!file)return;try{if(file.size>5000000)throw Error('Máximo de 5 MB por ficheiro.');$('csvImportError').textContent='A preparar a revisão…';const input=await file.text();if(token!==request||!dialog.open)return;if($('csvImportType').value==='players'){matching=CsvImport.reviewPlayers(master,input);showMatching();$('csvImportError').textContent='';}else{csvImportReview=CsvImport.plan(master,$('csvImportType').value,input);showPlan();}}catch(err){if(token===request&&dialog.open){csvImportReview=null;$('csvImportError').textContent=err.message;}}};
 $('csvImportConfirm').onclick=async()=>{
  if(!csvImportReview||busy)return;
  if(JSON.stringify(master)!==csvImportReview.baseline){csvImportReview=null;$('csvImportConfirm').hidden=true;$('csvImportError').textContent='A base mudou. Selecciona novamente o ficheiro para refazer a revisão.';return;}
  busy=true;const plan=csvImportReview;dialog.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);dialog.oncancel=e=>e.preventDefault();
  try{World.validate(plan.candidate);await AutoSave.replaceMaster(plan.candidate,plan.baseline);s=World.context(master);selectedPlayers.clear();dialog.close();render();message('Importação guardada. Base anterior disponível em Recuperação, neste navegador.');}
  catch(err){$('csvImportError').textContent='Não foi possível guardar: '+err.message;}
  finally{busy=false;dialog.oncancel=null;dialog.querySelectorAll('button,input,select').forEach(el=>el.disabled=false);}
 };dialog.showModal();
}
